+package com.example;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Anchor;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<Message> grid = new Grid<>();
+    private final MessageStore store;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+        name.setValue("");
+        email.setValue("");
+        phone.setValue("");
+        message.setValue("");
+        name.setRequiredIndicatorVisible(false);
+        email.setRequiredIndicatorVisible(false);
+        phone.setRequiredIndicatorVisible(false);
+        message.setRequiredIndicatorVisible(false);
+        message.setMaxLength(500);
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::message).setHeader("Message");
+        grid.setItems(store.newestFirst());
+        add(name, email, phone, message, send, grid);
+
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(Key.ENTER);
+        name.addKeyPressListener(Key.ENTER, event -> submit());
+        email.addKeyPressListener(Key.ENTER, event -> submit());
+        phone.addKeyPressListener(Key.ENTER, event -> submit());
+        message.addKeyPressListener(Key.ENTER, event -> submit());
+        name.addValueChangeListener(event -> edited());
+        email.addValueChangeListener(event -> edited());
+        phone.addValueChangeListener(event -> edited());
+        message.addValueChangeListener(event -> edited());
+    }
+
+    private void edited() {
+        send.setEnabled(true);
+    }
+
+    private void submit() {
+        String sender = name.getValue().trim();
+        String address = email.getValue().trim();
+        String number = phone.getValue().trim();
+        String body = message.getValue();
+        boolean valid = true;
+
+        name.setInvalid(sender.isEmpty());
+        if (sender.isEmpty()) {
+            name.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        boolean emailInvalid = !address.isEmpty() && !EMAIL.matcher(address).matches();
+        email.setInvalid(emailInvalid || (address.isEmpty() && number.isEmpty()));
+        if (emailInvalid) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (address.isEmpty() && number.isEmpty()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        boolean blankMessage = body == null || body.trim().isEmpty();
+        boolean tooLong = body != null && body.length() > 500;
+        message.setInvalid(blankMessage || tooLong);
+        if (blankMessage) {
+            message.setErrorMessage("Message is required");
+            valid = false;
+        } else if (tooLong) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) return;
+
+        store.add(new Message(sender, address, number, body));
+        grid.setItems(store.newestFirst());
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasDraft()) return;
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.add("You have an unsent message. Discard it?");
+        Button keep = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.add(keep, discard);
+        dialog.open();
+    }
+
+    private boolean hasDraft() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+}
